// User Activity Events Data Model for MooseStack
import { IngestPipeline } from "@514labs/moose-lib";

// Data model for user activity events
export interface UserActivityEvent {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number; // nullable duration values will default to 0
}

// IngestPipeline with optimized table ordering for our query patterns:
// 1. Activity counts per user over a date range (user_id, event_ts)
// 2. Total duration per action type (action)
export const UserActivityEventPipeline = new IngestPipeline<UserActivityEvent>("UserActivityEvent", {
  table: {
    orderByFields: ["user_id", "action", "event_ts"]
  },
  stream: true,
  ingestApi: true,
});

// Script to load sample user activity data into Moose
import * as fs from 'fs';

interface UserActivityEvent {
  event_id: string;
  event_ts: string; // ISO string format for JSON
  user_id: string;
  action: string;
  duration_ms: number;
}

async function loadSampleData() {
  try {
    // Read the CSV file
    const csvContent = fs.readFileSync('/data/samples/user_activity_sample.csv', 'utf-8');
    const lines = csvContent.trim().split('\n');

    // Skip header row
    const dataLines = lines.slice(1);

    console.log(`Processing ${dataLines.length} records...`);

    for (const line of dataLines) {
      if (line.trim() === '') continue;

      const [event_id, event_ts, user_id, action, duration_ms_str] = line.split(',');

      // Convert duration to number, default to 0 for null/empty values
      const duration_ms = duration_ms_str ? parseFloat(duration_ms_str) : 0;

      const event: UserActivityEvent = {
        event_id: event_id.trim(),
        event_ts: event_ts.trim(), // Keep as ISO string for JSON
        user_id: user_id.trim(),
        action: action.trim(),
        duration_ms: duration_ms
      };

      // Send to Moose ingestion API
      const response = await fetch('http://localhost:4000/ingest/UserActivityEvent', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(event)
      });

      if (response.ok) {
        console.log(`✓ Loaded event: ${event_id}`);
      } else {
        const error = await response.text();
        console.error(`✗ Failed to load event ${event_id}: ${error}`);
      }
    }

    console.log('Data loading completed!');

  } catch (error) {
    console.error('Error loading data:', error);
  }
}

loadSampleData();
